351	{
352	    if (m_decoration.slot_dots.empty() && m_decoration.slot_more.empty()) return 0;
353	    const SlotDotMetrics& metrics = m_theme.metrics().slot_dot;
354	    const int dot = FromDIP(m_decoration.small_slot_dots ? metrics.compact_size : metrics.size);
355	    const int gap = FromDIP(m_decoration.small_slot_dots ? metrics.compact_gap : metrics.gap);
356	    int width = int(m_decoration.slot_dots.size()) * (dot + gap);
357	    if (!m_decoration.slot_more.empty()) {
