366	wxSize HeaderButton::DoGetBestSize() const
367	{
368	    const ShellMetrics& m = m_theme.metrics();
369	    // No recipe covers a split action: its arrow half is the functional icon
370	    // plus a 12 DIP gutter, as tall as the status row it lives in.
371	    if (m_style == HeaderStyle::PrimaryRight) return FromDIP(wxSize(m.button.icon.icon_size + m.space_3, m.status_row.height));
372	    if (m_style == HeaderStyle::Outline) return FromDIP(wxSize(m.button.icon.width, m.button.icon.height));
373	    int label = GetTextExtent(GetLabel()).x;
374	    if (!m_decoration.sub_label.empty()) {
375	        wxClientDC dc(const_cast<HeaderButton*>(this));
376	        dc.SetFont(m_theme.font(TextRole::Metadata));
377	        label = std::max(label, dc.GetTextExtent(m_decoration.sub_label).x);
378	    }
379	    if (m_label_cap > 0) label = std::min(label, FromDIP(m_label_cap));
380	    if (!m_decoration.detail.empty() && m_decoration.detail_inline) {
381	        wxClientDC dc(const_cast<HeaderButton*>(this));
382	        dc.SetFont(detail_font());
383	        // Measured exactly as painted: " \xC2\xB7" plus a 3 DIP gap, or the chip
384	        // reserves space it never fills and the chevron drifts right.
385	        label += dc.GetTextExtent(wxString::FromUTF8(" \xC2\xB7")).x + FromDIP(3) +
386	                 dc.GetTextExtent(m_decoration.detail).x;
387	    }
388	    const int leading = FromDIP(12) + (m_icon == HeaderIcon::None ? 0 : FromDIP(24)) +
389	                        (m_decoration.dot.has_value() ? FromDIP(16) : 0) + lead_width() + slot_dots_width();
390	    // A two-line row is one spacing step taller than the menu row recipe;
391	    // the print action and the quiet buttons fill the status row.
392	    const int height = m_style == HeaderStyle::Menu ? (m_decoration.sub_label.empty() ? m.menu_row.height : m.menu_row.height + m.space_3) :
393	                       m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight ? m.chip.height : m.status_row.height;
394	    return {leading + label + trailing_reserve(), FromDIP(height)};
395	}
